 private final BroadcastReceiver packages=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){refreshApps();}};
 private static class App {String label,pkg,shortLabel;Intent intent;Bitmap icon,tile;long updated;boolean tv;}
 private static class Snapshot {List<App> order;Set<String> hidden,favorites;}
 private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private static int mod(int value,int size){return ((value%size)+size)%size;}
 private SharedPreferences prefs(){return getPreferences(0);}
 @Override public void onCreate(Bundle state){super.onCreate(state);loadFonts();hidden.addAll(prefs().getStringSet("ribbon_hidden",Collections.emptySet()));favorites.addAll(prefs().getStringSet("ribbon_favorites",Collections.emptySet()));restoreSelection=prefs().getString("selected",null);build();IntentFilter filter=new IntentFilter();filter.addAction(Intent.ACTION_PACKAGE_ADDED);filter.addAction(Intent.ACTION_PACKAGE_REMOVED);filter.addAction(Intent.ACTION_PACKAGE_CHANGED);filter.addDataScheme("package");registerReceiver(packages,filter);refreshApps();}
 @Override protected void onResume(){super.onResume();active=true;launching=false;if(editor!=null)closeModal(false);String returned=prefs().getString("return_app",null);if(returned!=null){restoreSelection=returned;prefs().edit().remove("return_app").apply();selectPackage(returned);}if(carousel!=null)carousel.requestFocus();if(!loading&&SystemClock.elapsedRealtime()-lastRefresh>30000)refreshApps();}
 @Override protected void onPause(){active=false;launching=false;if(carousel!=null){carousel.freeze();rememberSelection();}if(heroIcon!=null)heroIcon.animate().cancel();super.onPause();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);launching=false;if(editor!=null)closeModal(false);carousel.requestFocus();}
 @Override protected void onDestroy(){destroyed=true;main.removeCallbacksAndMessages(null);worker.shutdownNow();try{unregisterReceiver(packages);}catch(Exception ignored){}super.onDestroy();}
 @Override public void onBackPressed(){if(editor!=null){closeModal(true);return;}carousel.requestFocus();}
 @Override public boolean dispatchKeyEvent(KeyEvent event){if(editor!=null&&event.getAction()==KeyEvent.ACTION_DOWN){int key=event.getKeyCode(),direction=key==21?View.FOCUS_LEFT:key==22?View.FOCUS_RIGHT:key==19?View.FOCUS_UP:key==20?View.FOCUS_DOWN:0;View focused=editor.findFocus();if(direction!=0&&!(focused instanceof EditText&&(key==21||key==22))){View next=focused==null?null:focused.focusSearch(direction);if(next==null||!insideEditor(next))return true;}}return super.dispatchKeyEvent(event);}
 private void loadFonts(){try{if(Build.VERSION.SDK_INT>=26){regular=new Typeface.Builder(getAssets(),"fonts/Manrope.ttf").setFontVariationSettings("'wght' 400").setWeight(400).build();light=new Typeface.Builder(getAssets(),"fonts/Manrope.ttf").setFontVariationSettings("'wght' 300").setWeight(300).build();}else{regular=Typeface.createFromAsset(getAssets(),"fonts/Manrope.ttf");light=regular;}if(regular==null||light==null)throw new IllegalStateException("Font unavailable");fontName="Manrope";android.graphics.Paint check=new android.graphics.Paint();check.setTypeface(regular);android.util.Log.i("OurTV","Font loaded: Manrope; Cyrillic="+check.hasGlyph("Ж"));}catch(Exception e){regular=Typeface.create("sans-serif",0);light=Typeface.create("sans-serif-light",0);android.util.Log.e("OurTV","Manrope load failed",e);}}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setTypeface(regular);t.setIncludeFontPadding(false);return t;}
 private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView chip(String label,Runnable action){TextView b=text(label,12,MUTED);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),dp(9),dp(12),dp(9));b.setFocusable(true);b.setClickable(true);b.setId(View.generateViewId());b.setBackground(new FocusGlass(16,b));b.setOnClickListener(v->{if(!closingModal)action.run();});return b;}
 private String selectedPackage(){return apps.isEmpty()?restoreSelection:apps.get(mod(Math.round(carousel.position),apps.size())).pkg;}
 private void rememberSelection(){String pkg=selectedPackage();if(pkg!=null)prefs().edit().putString("selected",pkg).apply();}
 private void selectPackage(String pkg){if(carousel==null||apps.isEmpty())return;for(int i=0;i<apps.size();i++)if(apps.get(i).pkg.equals(pkg)){carousel.freeze();carousel.position=carousel.target=i;displayedApp=-1;select(false);carousel.invalidate();return;}}
 private int priority(String p){if(p.equals("com.google.android.youtube.tv"))return 0;if(p.contains("netflix"))return 1;if(p.equals("com.spotify.tv.android"))return 2;if(p.equals("ru.kinopoisk.tv"))return 3;return 4;}
 private void refreshApps(){if(destroyed)return;if(loading){refreshAgain=true;return;}loading=true;final String keep=selectedPackage();final Map<String,App> cached=new HashMap<>();for(App a:catalog)cached.put(a.pkg,a);worker.execute(()->{try{List<App> result=scanApps(cached);main.post(()->{if(destroyed)return;String current=selectedPackage();catalog.clear();catalog.addAll(result);sortStoredOrder();rebuildRibbon(current);loading=false;lastRefresh=SystemClock.elapsedRealtime();if(modalKind.equals("editor"))renderEditor(null);else if(modalKind.equals("search"))renderSearch();android.util.Log.i("OurTV","Catalog ready: "+catalog.size()+" apps, "+apps.size()+" visible");if(refreshAgain){refreshAgain=false;refreshApps();}});}catch(Exception error){android.util.Log.e("OurTV","Catalog refresh failed",error);main.post(()->{if(destroyed)return;loading=false;if(apps.isEmpty())title.setText("Не удалось загрузить приложения");Toast.makeText(this,"Не удалось обновить список приложений",0).show();});}});}
 private List<App> scanApps(Map<String,App> cached){PackageManager pm=getPackageManager();LinkedHashMap<String,ResolveInfo> found=new LinkedHashMap<>();Set<String> tv=new HashSet<>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo info:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0)){String pkg=info.activityInfo.packageName;if(pkg.equals(getPackageName())||!info.activityInfo.exported)continue;if(category.equals(Intent.CATEGORY_LEANBACK_LAUNCHER))tv.add(pkg);if(!found.containsKey(pkg))found.put(pkg,info);}List<App> result=new ArrayList<>();for(Map.Entry<String,ResolveInfo> entry:found.entrySet()){if(Thread.currentThread().isInterrupted())break;String pkg=entry.getKey();try{ResolveInfo info=entry.getValue();long updated=pm.getPackageInfo(pkg,0).lastUpdateTime;App old=cached.get(pkg);if(old!=null&&old.updated==updated&&old.intent.getComponent().getClassName().equals(info.activityInfo.name)){result.add(old);continue;}App a=new App();a.pkg=pkg;a.updated=updated;a.tv=tv.contains(pkg);a.label=info.loadLabel(pm).toString();a.intent=new Intent(Intent.ACTION_MAIN).setClassName(pkg,info.activityInfo.name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);a.icon=loadOriginalIcon(info,updated);prepareTile(a);result.add(a);}catch(Exception error){android.util.Log.w("OurTV","Skipped unavailable package: "+pkg,error);}}Collections.sort(result,(a,b)->{int x=priority(a.pkg),y=priority(b.pkg);return x!=y?x-y:a.label.compareToIgnoreCase(b.label);});App own=new App();own.pkg="settings";own.label="Настройки";prepareTile(own);result.add(own);return result;}
 private Bitmap loadOriginalIcon(ResolveInfo info,long updated)throws Exception{File dir=new File(getCacheDir(),"original-icons-v4");dir.mkdirs();File file=new File(dir,info.activityInfo.packageName+"-"+updated+".png");if(file.isFile()){Bitmap saved=BitmapFactory.decodeFile(file.getAbsolutePath());if(saved!=null)return saved;}Drawable source=info.loadIcon(getPackageManager());if(source instanceof AdaptiveIconDrawable)source=((AdaptiveIconDrawable)source).getForeground();Bitmap bitmap=Bitmap.createBitmap(320,320,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);int iw=Math.max(1,source.getIntrinsicWidth()),ih=Math.max(1,source.getIntrinsicHeight());float scale=Math.min(320f/iw,320f/ih);int w=Math.round(iw*scale),h=Math.round(ih*scale);source.setBounds((320-w)/2,(320-h)/2,(320+w)/2,(320+h)/2);source.draw(c);int[] input=new int[320*320];bitmap.getPixels(input,0,320,0,0,320,320);int[] pixels=IconPixels.clean(input,320,320);String pkg=info.activityInfo.packageName;if(pkg.equals("com.espn.score_center")||pkg.equals("com.netflix.ninja"))pixels=IconPixels.redWordmark(pixels);bitmap.setPixels(pixels,0,320,0,0,320,320);int l=320,t=320,r=-1,b=-1;for(int y=0;y<320;y++)for(int x=0;x<320;x++)if((pixels[y*320+x]>>>24)>28){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}Bitmap cropped=r>=l?Bitmap.createBitmap(bitmap,l,t,r-l+1,b-t+1):bitmap;try(FileOutputStream stream=new FileOutputStream(file)){cropped.compress(Bitmap.CompressFormat.PNG,100,stream);}catch(IOException ignored){}return cropped;}
 private void prepareTile(App app){app.tile=Bitmap.createBitmap(232,130,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(app.tile);CardArt d=new CardArt(app);d.setBounds(0,0,232,130);d.draw(c);TextPaint p=new TextPaint(3);p.setTypeface(regular);p.setTextSize(dp(11));app.shortLabel=TextUtils.ellipsize(app.label,p,dp(160),TextUtils.TruncateAt.END).toString();}
 private void sortStoredOrder(){final Map<String,Integer> order=new HashMap<>();try{org.json.JSONArray data=new org.json.JSONArray(prefs().getString("ribbon_order","[]"));for(int i=0;i<data.length();i++)order.put(data.getString(i),i);}catch(Exception ignored){}Collections.sort(catalog,(a,b)->Integer.compare(order.getOrDefault(a.pkg,100000),order.getOrDefault(b.pkg,100000)));}
 private void rebuildRibbon(String keep){carousel.freeze();List<App> ordered=new ArrayList<>(catalog);Collections.sort(ordered,(a,b)->Boolean.compare(favorites.contains(b.pkg),favorites.contains(a.pkg)));apps.clear();for(App a:ordered)if(!hidden.contains(a.pkg))apps.add(a);if(apps.isEmpty()&&!catalog.isEmpty()){App a=catalog.get(0);hidden.remove(a.pkg);apps.add(a);}int index=0;String wanted=keep!=null?keep:restoreSelection;for(int i=0;i<apps.size();i++)if(apps.get(i).pkg.equals(wanted))index=i;carousel.position=carousel.target=index;displayedApp=-1;select(false);carousel.invalidate();}
 private void saveRibbon(){org.json.JSONArray order=new org.json.JSONArray();for(App a:catalog)order.put(a.pkg);prefs().edit().putString("ribbon_order",order.toString()).putStringSet("ribbon_hidden",new HashSet<>(hidden)).putStringSet("ribbon_favorites",new HashSet<>(favorites)).apply();}
 private void select(boolean animate){if(apps.isEmpty())return;int index=mod(Math.round(carousel.position),apps.size());if(index==displayedApp)return;displayedApp=index;App a=apps.get(index);title.setText(a.label);heroIcon.animate().cancel();heroIcon.setImageDrawable(new CardArt(a));favoriteMark.setVisibility(favorites.contains(a.pkg)?View.VISIBLE:View.GONE);carousel.setContentDescription(a.label+(favorites.contains(a.pkg)?", закреплено":""));if(animate&&active&&prefs().getBoolean("animations",true)){heroIcon.setAlpha(.96f);heroIcon.animate().alpha(1).setDuration(120).start();}else heroIcon.setAlpha(1f);}
 private void launchSelected(){if(apps.isEmpty())return;carousel.target=Math.round(carousel.position);select(false);launch(apps.get(mod(carousel.target,apps.size())),heroCard);}
 private void launch(App app,View anchor){if(app.pkg.equals("settings")){if(editor!=null)closeModal(false);openSettings();return;}long now=SystemClock.elapsedRealtime();if(launching||now-lastLaunchAt<350)return;lastLaunchAt=now;launching=true;rememberSelection();try{Bundle options=null;if(prefs().getBoolean("animations",true)&&anchor.getWidth()>0){int w=Math.max(1,heroCard.getWidth()),h=Math.max(1,heroCard.getHeight());Bitmap thumb=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);CardArt card=new CardArt(app);card.setBounds(0,0,w,h);card.draw(new Canvas(thumb));options=ActivityOptions.makeThumbnailScaleUpAnimation(anchor,thumb,0,0).toBundle();}prefs().edit().putString("return_app",app.pkg).apply();android.util.Log.i("OurTV","Launch requested immediately: "+app.pkg);startActivity(new Intent(app.intent),options);main.postDelayed(()->launching=false,1200);}catch(Exception error){launching=false;prefs().edit().remove("return_app").apply();android.util.Log.w("OurTV","Cannot launch "+app.pkg,error);Toast.makeText(this,"Приложение недоступно. Обновляю список.",0).show();refreshApps();}}
 private void systemPage(String action){try{startActivity(new Intent(action));}catch(Exception first){try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception error){Toast.makeText(this,"Этот раздел недоступен на приставке",0).show();}}}
 private void build(){getWindow().setFlags(1024,1024);getWindow().getDecorView().setSystemUiVisibility(5894);scene=new FrameLayout(this);scene.setBackgroundColor(0xff111111);setContentView(scene);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView mark=text("TV",17,WHITE);mark.setLetterSpacing(.08f);header.addView(mark,new LinearLayout.LayoutParams(0,-2,1));searchButton=chip("Поиск",()->openSearch());customize=chip("Настроить ленту",()->openEditor());settings=chip("Настройки",()->openSettings());for(TextView button:new TextView[]{searchButton,customize,settings}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.leftMargin=dp(10);header.addView(button,p);}TextClock clock=new TextClock(this);clock.setFormat24Hour("HH:mm");clock.setFormat12Hour("HH:mm");clock.setTypeface(light);clock.setTextSize(16);clock.setTextColor(MUTED);clock.setPadding(dp(24),0,0,0);header.addView(clock);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,dp(38),Gravity.TOP);hp.setMargins(dp(44),dp(22),dp(44),0);scene.addView(header,hp);title=text("Загрузка приложений…",34,WHITE);title.setTypeface(light);title.setLetterSpacing(-.025f);title.setGravity(Gravity.CENTER);title.setSingleLine(true);title.setEllipsize(TextUtils.TruncateAt.END);FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(-1,dp(48),Gravity.TOP);tp.topMargin=dp(84);tp.leftMargin=dp(80);tp.rightMargin=dp(80);scene.addView(title,tp);heroCard=new FrameLayout(this);heroCard.setBackground(round(0xff171717,20));heroCard.setClipToOutline(true);heroCard.setElevation(dp(18));heroCard.setOnClickListener(v->launchSelected());heroCard.setFocusable(false);heroCard.setOnHoverListener((v,e)->{if(heroEdge!=null)heroEdge.setActive(e.getAction()!=MotionEvent.ACTION_HOVER_EXIT||carousel!=null&&carousel.hasFocus());return false;});heroIcon=new ImageView(this);heroIcon.setScaleType(ImageView.ScaleType.FIT_XY);heroCard.addView(heroIcon,new FrameLayout.LayoutParams(-1,-1));View edge=new View(this);heroEdge=new HeroEdge();edge.setBackground(heroEdge);heroCard.addView(edge,new FrameLayout.LayoutParams(-1,-1));favoriteMark=text("★",13,Color.WHITE);FrameLayout.LayoutParams star=new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.TOP|Gravity.LEFT);star.setMargins(dp(12),dp(10),0,0);heroCard.addView(favoriteMark,star);favoriteMark.setVisibility(View.GONE);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(300),dp(169),Gravity.CENTER);heroCard.setTranslationY(-dp(29));scene.addView(heroCard,ip);carousel=new Carousel();carousel.setId(View.generateViewId());carousel.setFocusable(true);carousel.setFocusableInTouchMode(true);carousel.setBackground(new Glass(26));carousel.setClipToOutline(true);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,dp(160),Gravity.BOTTOM);cp.setMargins(dp(36),0,dp(36),dp(34));scene.addView(carousel,cp);for(TextView button:new TextView[]{searchButton,customize,settings})button.setNextFocusDownId(carousel.getId());searchButton.setNextFocusRightId(customize.getId());customize.setNextFocusLeftId(searchButton.getId());customize.setNextFocusRightId(settings.getId());settings.setNextFocusLeftId(customize.getId());carousel.setNextFocusUpId(searchButton.getId());carousel.requestFocus();}
 private boolean insideEditor(View v){for(android.view.ViewParent p=v.getParent();p!=null;p=p.getParent())if(p==editor)return true;return v==editor;}
 private void panel(String heading,String subtitle,String kind,View origin){if(editor!=null)closeModal(false);modalKind=kind;modalOrigin=origin;closingModal=false;carousel.freeze();editor=new FrameLayout(this);editor.setElevation(dp(32));editor.setBackgroundColor(0xe6111111);scene.addView(editor,new FrameLayout.LayoutParams(-1,-1));modalPanel=new LinearLayout(this);modalPanel.setOrientation(LinearLayout.VERTICAL);modalPanel.setPadding(dp(24),dp(22),dp(24),dp(18));modalPanel.setBackground(new Glass(26));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-1);p.setMargins(dp(64),dp(38),dp(64),dp(38));editor.addView(modalPanel,p);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=text(heading,24,WHITE);name.setTypeface(light);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));modalDone=chip("Готово",()->closeModal(true));row.addView(modalDone);modalPanel.addView(row);if(!subtitle.isEmpty()){TextView description=text(subtitle,12,MUTED);description.setPadding(0,dp(10),0,dp(16));modalPanel.addView(description);}else{View gap=new View(this);modalPanel.addView(gap,new LinearLayout.LayoutParams(1,dp(14)));}if(prefs().getBoolean("animations",true)){editor.setAlpha(0);modalPanel.setTranslationY(dp(12));editor.animate().alpha(1).setDuration(160).start();modalPanel.animate().translationY(0).setDuration(200).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();}}
 private void rows(){ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);editorRows=new LinearLayout(this);editorRows.setOrientation(LinearLayout.VERTICAL);scroll.addView(editorRows);modalPanel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private void closeModal(boolean animate){if(editor==null||(closingModal&&animate))return;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(editor.getWindowToken(),0);if(searchTask!=null)main.removeCallbacks(searchTask);FrameLayout old=editor;View origin=modalOrigin;String oldKind=modalKind;closingModal=true;old.animate().cancel();Runnable finish=()->{scene.removeView(old);if(editor==old){editor=null;editorRows=null;searchInput=null;modalKind="";closingModal=false;if(active&&origin!=null)origin.requestFocus();}android.util.Log.i("OurTV","Panel closed: "+oldKind);};if(animate&&prefs().getBoolean("animations",true))old.animate().alpha(0).setDuration(120).withEndAction(finish).start();else finish.run();}
 private void openSettings(){panel("Настройки","", "settings",settings);rows();settingRow("Настроить ленту",()->openEditor());settingRow("Поиск приложений",()->openSearch());final TextView[] animationSwitch=new TextView[1];animationSwitch[0]=settingRow("Плавные переходы: "+(prefs().getBoolean("animations",true)?"включены":"выключены"),()->{boolean enabled=!prefs().getBoolean("animations",true);prefs().edit().putBoolean("animations",enabled).apply();animationSwitch[0].setText("Плавные переходы: "+(enabled?"включены":"выключены"));});settingRow("Wi-Fi и сеть  ›",()->systemPage(Settings.ACTION_WIFI_SETTINGS));settingRow("Bluetooth и пульты  ›",()->systemPage(Settings.ACTION_BLUETOOTH_SETTINGS));settingRow("Экран  ›",()->systemPage(Settings.ACTION_DISPLAY_SETTINGS));settingRow("Звук  ›",()->systemPage(Settings.ACTION_SOUND_SETTINGS));settingRow("Приложения Android  ›",()->systemPage(Settings.ACTION_MANAGE_APPLICATIONS_SETTINGS));settingRow("Обновить список приложений",()->{refreshApps();Toast.makeText(this,"Обновляю приложения",0).show();});settingRow("Все настройки Android  ›",()->systemPage(Settings.ACTION_SETTINGS));settingRow("О лаунчере",()->{panel("Наш TV","", "about",settings);TextView info=text("Версия 18\n\n"+Build.MODEL+" · Android "+Build.VERSION.RELEASE+"\n\nПриложений: "+catalog.size()+" · В ленте: "+apps.size()+"\n\nШрифт: "+fontName,16,MUTED);info.setPadding(0,dp(16),0,0);modalPanel.addView(info);});focusFirstRow();}
 private TextView settingRow(String label,Runnable action){TextView button=chip(label,action);button.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(42));p.bottomMargin=dp(7);editorRows.addView(button,p);return button;}
 private void focusFirstRow(){if(editorRows!=null&&editorRows.getChildCount()>0){View child=editorRows.getChildAt(0);child.post(()->{if(editor!=null)child.requestFocus();});}}
 private static String normalized(String value){return value.toLowerCase(java.util.Locale.ROOT).replace('ё','е').trim();}
 private void openSearch(){panel("Поиск","", "search",searchButton);searchInput=new EditText(this);searchInput.setTextColor(WHITE);searchInput.setHintTextColor(0xff737373);searchInput.setHint("Название приложения");searchInput.setTextSize(19);searchInput.setTypeface(regular);searchInput.setSingleLine(true);searchInput.setPadding(dp(16),dp(10),dp(16),dp(10));searchInput.setBackground(new FocusGlass(14,null));modalPanel.addView(searchInput,new LinearLayout.LayoutParams(-1,dp(48)));View gap=new View(this);modalPanel.addView(gap,new LinearLayout.LayoutParams(1,dp(12)));rows();searchInput.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(searchTask!=null)main.removeCallbacks(searchTask);searchTask=()->renderSearch();main.postDelayed(searchTask,100);}public void afterTextChanged(Editable e){}});renderSearch();searchInput.requestFocus();searchInput.setOnEditorActionListener((v,action,event)->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);focusFirstRow();return true;});}
 private void renderSearch(){if(!modalKind.equals("search")||editorRows==null||searchInput==null)return;editorRows.removeAllViews();String query=normalized(searchInput.getText().toString());int count=0;List<App> ordered=new ArrayList<>(catalog);Collections.sort(ordered,(a,b)->Boolean.compare(favorites.contains(b.pkg),favorites.contains(a.pkg)));for(App app:ordered){if(!SearchQuery.matches(app.label,app.pkg,query))continue;TextView result=chip((favorites.contains(app.pkg)?"★  ":"")+app.label+(hidden.contains(app.pkg)?"  ·  Скрыто в ленте":""),()->{View anchor=editorRows==null?heroCard:editorRows;launch(app,anchor);});result.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(43));p.bottomMargin=dp(7);editorRows.addView(result,p);count++;}if(count==0){TextView empty=text(loading?"Загрузка…":"Ничего не найдено",16,MUTED);empty.setPadding(0,dp(18),0,0);editorRows.addView(empty);}}
 private void openEditor(){panel("Настроить ленту","★ Закреплённые идут первыми · Изменения сохраняются сразу", "editor",customize);undo=null;undoButton=chip("Отменить изменение",()->undoEdit());undoButton.setEnabled(false);undoButton.setFocusable(false);undoButton.setAlpha(.3f);modalPanel.addView(undoButton,new LinearLayout.LayoutParams(-2,dp(34)));View gap=new View(this);modalPanel.addView(gap,new LinearLayout.LayoutParams(1,dp(10)));rows();String selected=selectedPackage();renderEditor(selected==null?null:selected+":favorite");}
 private void renderEditor(String focusTag){if(!modalKind.equals("editor")||editorRows==null)return;editorRows.removeAllViews();List<App> ordered=new ArrayList<>(catalog);Collections.sort(ordered,(a,b)->Boolean.compare(favorites.contains(b.pkg),favorites.contains(a.pkg)));View exact=null,first=null;for(int i=0;i<ordered.size();i++){final App app=ordered.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(5),dp(8),dp(5));row.setAddStatesFromChildren(true);row.setBackground(new FocusGlass(12,null));TextView label=text((favorites.contains(app.pkg)?"★  ":"")+app.label+(hidden.contains(app.pkg)?"  ·  Скрыто":""),13,hidden.contains(app.pkg)?0xff777777:WHITE);label.setSingleLine(true);label.setEllipsize(TextUtils.TruncateAt.END);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));String[] actions={"favorite","up","down","hidden"},labels={favorites.contains(app.pkg)?"★ Открепить":"☆ Закрепить","↑","↓",hidden.contains(app.pkg)?"Показать":"Скрыть"};for(int a=0;a<4;a++){final String action=actions[a];TextView button=chip(labels[a],()->editApp(app,action));String tag=app.pkg+":"+action;button.setTag(tag);button.setContentDescription(app.label+": "+labels[a]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(a==0?125:a==3?88:40),dp(34));p.leftMargin=dp(6);row.addView(button,p);boolean enabled=a!=1&&a!=2||(a==1&&i>0&&favorites.contains(app.pkg)==favorites.contains(ordered.get(i-1).pkg))||(a==2&&i<ordered.size()-1&&favorites.contains(app.pkg)==favorites.contains(ordered.get(i+1).pkg));button.setEnabled(enabled);button.setFocusable(enabled);button.setAlpha(enabled?1:.25f);if(enabled&&first==null)first=button;if(enabled&&tag.equals(focusTag))exact=button;}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(46));p.bottomMargin=dp(6);editorRows.addView(row,p);}if(exact==null&&focusTag!=null){String alternate=focusTag.endsWith(":down")?focusTag.replace(":down",":up"):focusTag.endsWith(":up")?focusTag.replace(":up",":down"):focusTag;View same=editorRows.findViewWithTag(alternate);if(same!=null&&same.isFocusable())exact=same;else exact=editorRows.findViewWithTag(focusTag.substring(0,focusTag.lastIndexOf(':'))+":favorite");}if(first!=null&&undoButton!=null){first.setNextFocusUpId(undoButton.isEnabled()?undoButton.getId():modalDone.getId());undoButton.setNextFocusDownId(first.getId());undoButton.setNextFocusUpId(modalDone.getId());}final View target=exact!=null?exact:first;if(target!=null)target.post(()->{if(modalKind.equals("editor"))target.requestFocus();});}
 private Snapshot snapshot(){Snapshot s=new Snapshot();s.order=new ArrayList<>(catalog);s.hidden=new HashSet<>(hidden);s.favorites=new HashSet<>(favorites);return s;}
 private void undoEdit(){if(undo==null)return;String keep=selectedPackage();catalog.clear();catalog.addAll(undo.order);hidden.clear();hidden.addAll(undo.hidden);favorites.clear();favorites.addAll(undo.favorites);undo=null;saveRibbon();rebuildRibbon(keep);undoButton.setEnabled(false);undoButton.setFocusable(false);undoButton.setAlpha(.3f);renderEditor(null);}
 private void editApp(App app,String action){String keep=selectedPackage();Snapshot before=snapshot();if(action.equals("favorite")){if(!favorites.remove(app.pkg))favorites.add(app.pkg);}else if(action.equals("hidden")){if(hidden.contains(app.pkg))hidden.remove(app.pkg);else{if(apps.size()==1){Toast.makeText(this,"Оставьте хотя бы одно приложение",0).show();return;}hidden.add(app.pkg);}}else{List<App> group=new ArrayList<>();for(App a:catalog)if(favorites.contains(a.pkg)==favorites.contains(app.pkg))group.add(a);int from=group.indexOf(app),to=from+(action.equals("up")?-1:1);if(to<0||to>=group.size())return;App other=group.get(to);Collections.swap(catalog,catalog.indexOf(app),catalog.indexOf(other));}undo=before;undoButton.setEnabled(true);undoButton.setFocusable(true);undoButton.setAlpha(1);saveRibbon();rebuildRibbon(keep);renderEditor(app.pkg+":"+action);android.util.Log.i("OurTV","Ribbon edit: "+app.pkg+" "+action);}
