  @Override public boolean onKeyDown(int key,KeyEvent event){if(key==21){move(-1);return true;}if(key==22){move(1);return true;}if(key==19){searchButton.requestFocus();return true;}if(key==20)return true;if(key==23||key==66){if(event.getRepeatCount()==0)launchSelected();return true;}return super.onKeyDown(key,event);}
