  @Override public boolean onTouchEvent(android.view.MotionEvent e){if(apps.isEmpty())return false;if(e.getAction()==0){requestFocus();freeze();touchX=e.getX();touchPosition=position;dragged=false;return true;}if(e.getAction()==2){if(Math.abs(e.getX()-touchX)>dp(8))dragged=true;if(dragged){position=touchPosition-(e.getX()-touchX)/dp(178);target=Math.round(position);select(false);invalidate();}return true;}if(e.getAction()==1){if(dragged){target=Math.round(position);start();}else{int hit=Math.round(position+(e.getX()-getWidth()/2f)/dp(178));if(hit==Math.round(position))performClick();else{target=hit;start();}}return true;}return true;}
